declare(strict_types=1);
$root=dirname(__DIR__);require_once $root.'/includes/updater/UpdateException.php';require_once $root.'/includes/updater/UpdateRuntime.php';require_once $root.'/includes/updater/UpdateService.php';
function us_ok($v,string $m):void{if(!$v){fwrite(STDERR,"FAIL: {$m}\n");exit(1);}}
$expected=['fetch_manifest','preflight','download','stage_archive','backup_source','backup_database','lock_update','migrate','apply_files','post_verify','cleanup','rollback_migrations','rollback_source','rollback_finalize'];foreach($expected as $stage){us_ok(in_array($stage,UpdateService::STAGES,true),'missing state '.$stage);} $lock=(string)file_get_contents($root.'/includes/updater/UpdateLock.php');foreach(['Retry-After: 5','UPDATE_IN_PROGRESS','updates\\.php','login\\.php','update-[A-Za-z0-9_-]+\\.php'] as $marker){us_ok(strpos($lock,$marker)!==false,'update-lock recovery contract missing '.$marker);} $spec=json_decode((string)file_get_contents($root.'/update/release-spec.json'),true);us_ok(($spec['version']??'')==='5.8.3','release spec version');us_ok(($spec['channel']??'')==='stable','release spec stable channel');us_ok(($spec['upgrade_from']??[])===['5.8.2'],'v5.8.3 release spec accepts frozen v5.8.2 baseline');us_ok(count($spec['migrations']??[])===1 && ($spec['migrations'][0]['path']??'')==='migration-v5.8.3-admin-license-api.sql','v5.8.3 release spec declares Admin API migration');foreach($spec['migrations']??[] as $m){us_ok(!empty($m['idempotent'])||(!empty($m['destructive'])&&!empty($m['rollback_path'])),'migration must be idempotent or rollback-protected');}echo "Updater state-machine checks passed.\n";
